 31→// ---------------------------------------------------------------------------
 32→// Loader
 33→// ---------------------------------------------------------------------------
 34→
 35→export const loader = async ({ request }: LoaderFunctionArgs) => {
 36→  const { session } = await authenticate.admin(request);
 37→  const shop = session.shop;
 38→
 39→  const [subscription, zipCount, shopSettings] = await Promise.all([
 40→    getShopSubscription(shop),
 41→    db.zipCode.count({ where: { shop } }),
 42→    db.shopSettings.findUnique({ where: { shop } }),
 43→  ]);
 44→
 45→  return {
 46→    subscription,
 47→    zipCount,
 48→    shop,
 49→    defaultBehavior: shopSettings?.defaultBehavior ?? "block",
 50→    notificationEmail: shopSettings?.notificationEmail ?? "",
 51→    emailSenderName: shopSettings?.emailSenderName ?? "",
 52→    emailReplyTo: shopSettings?.emailReplyTo ?? "",
 53→  };
 54→};
 55→
 56→// ---------------------------------------------------------------------------
 57→// Action
 58→// ---------------------------------------------------------------------------
 59→
 60→export const action = async ({ request }: ActionFunctionArgs) => {
 61→  const { session } = await authenticate.admin(request);
 62→  const shop = session.shop;
 63→
 64→  const formData = await request.formData();
 65→  const intent = formData.get("intent") as string;
 66→
 67→  try {
 68→    if (intent === "save-behavior") {
 69→      const defaultBehavior = formData.get("defaultBehavior") as string;
 70→      if (defaultBehavior !== "block" && defaultBehavior !== "allow") {
 71→        return { error: "Invalid value for defaultBehavior" };
 72→      }
 73→      await db.shopSettings.upsert({
 74→        where: { shop },
 75→        create: { shop, defaultBehavior },
 76→        update: { defaultBehavior },
 77→      });
 78→      return { success: true, intent };
 79→    }
 80→
 81→    if (intent === "save-notification") {
 82→      const notificationEmail =
 83→        (formData.get("notificationEmail") as string | null) ?? "";
 84→      await db.shopSettings.upsert({
 85→        where: { shop },
 86→        create: { shop, notificationEmail: notificationEmail || null },
 87→        update: { notificationEmail: notificationEmail || null },
 88→      });
 89→      return { success: true, intent };
 90→    }
 91→
 92→    if (intent === "save-email-settings") {
 93→      const emailSenderName =
 94→        (formData.get("emailSenderName") as string | null)?.trim() || null;
 95→      const emailReplyTo =
 96→        (formData.get("emailReplyTo") as string | null)?.trim() || null;
 97→      await db.shopSettings.upsert({
 98→        where: { shop },
 99→        create: { shop, emailSenderName, emailReplyTo },
100→        update: { emailSenderName, emailReplyTo },
101→      });
102→      return { success: true, intent };
103→    }
104→
105→    if (intent === "send-test-email") {
106→      const testEmail = (formData.get("testEmail") as string | null) ?? "";
107→      if (!testEmail) return { error: "No email address provided." };
108→      const settings = await db.shopSettings.findUnique({ where: { shop } });
109→      const sent = await sendTestEmail(
110→        testEmail,
111→        { senderName: settings?.emailSenderName, replyTo: settings?.emailReplyTo },
112→        shop,
113→      );
114→      return sent
115→        ? { success: true, intent }
116→        : { error: "Failed to send test email. Check your Resend API key and sender email." };
117→    }
118→
119→    return { error: "Unknown intent" };
120→  } catch {
121→    return { error: "Failed to save settings. Please try again." };
122→  }
123→};
