  1→/**
  2→ * Centralized Resend email service.
  3→ *
  4→ * All send functions return `true` on success, `false` on failure — they never
  5→ * throw. This lets callers fire-and-forget without wrapping in try/catch.
  6→ */
  7→import { Resend } from "resend";
  8→
  9→// ---------------------------------------------------------------------------
 10→// Types
 11→// ---------------------------------------------------------------------------
 12→
 13→export interface EmailOptions {
 14→  /** Display name in the From field (e.g. "Cool Store"). Defaults to shop name + "via Pinzo". */
 15→  senderName?: string | null;
 16→  /** Reply-to email for customer-facing emails. If empty, no reply-to header is added. */
 17→  replyTo?: string | null;
 18→}
 19→
 20→// ---------------------------------------------------------------------------
 21→// Client singleton
 22→// ---------------------------------------------------------------------------
 23→
 24→let client: Resend | null = null;
 25→
 26→function getClient(): Resend | null {
 27→  if (client) return client;
 28→  const apiKey = process.env.RESEND_API_KEY;
 29→  if (!apiKey) {
 30→    console.warn("[email] RESEND_API_KEY not set — emails will be skipped");
 31→    return null;
 32→  }
 33→  client = new Resend(apiKey);
 34→  return client;
 35→}
 36→
 37→function getRawFromEmail(): string {
 38→  return process.env.RESEND_FROM_EMAIL || "noreply@example.com";
 39→}
 40→
 41→function shopDisplayName(shop: string): string {
 42→  return shop.replace(".myshopify.com", "");
 43→}
 44→
 45→/**
 46→ * Build the full From address with display name.
 47→ *
 48→ * - Custom sender name set:  "Cool Store via Pinzo <noreply@boldteq.app>"
 49→ * - No custom name:          "cool-store via Pinzo <noreply@boldteq.app>"
 50→ */
 51→function buildFrom(shop: string, options?: EmailOptions): string {
 52→  const displayName = options?.senderName?.trim() || shopDisplayName(shop);
 53→  return `${displayName} via Pinzo <${getRawFromEmail()}>`;
 54→}
 55→
 56→/**
 57→ * Build optional reply_to field. Returns undefined when not configured
 58→ * so it can be spread into the Resend payload without adding an empty header.
 59→ */
 60→function buildReplyTo(options?: EmailOptions): { reply_to: string } | Record<string, never> {
 61→  const replyTo = options?.replyTo?.trim();
 62→  if (replyTo) return { reply_to: replyTo };
 63→  return {};
 64→}
 65→
 66→// ---------------------------------------------------------------------------
 67→// 1. Waitlist Confirmation  (App → Customer)
 68→// ---------------------------------------------------------------------------
 69→
 70→export async function sendWaitlistConfirmation(
 71→  to: string,
 72→  zipCode: string,
 73→  shop: string,
 74→  options?: EmailOptions,
 75→): Promise<boolean> {
 76→  const resend = getClient();
 77→  if (!resend) return false;
 78→
 79→  const name = options?.senderName?.trim() || shopDisplayName(shop);
 80→
 81→  try {
 82→    await resend.emails.send({
 83→      from: buildFrom(shop, options),
 84→      to,
 85→      subject: `You're on the waitlist — ${name}`,
 86→      html: `
 87→        <div style="font-family:Arial,sans-serif;max-width:560px;margin:0 auto;padding:24px">
 88→          <h2 style="margin:0 0 16px">You're on the waitlist!</h2>
 89→          <p>Thanks for signing up. We'll let you know as soon as delivery is available to <strong>${zipCode}</strong>.</p>
 90→          <p style="color:#666;font-size:13px;margin-top:24px">— ${name}</p>
 91→        </div>
 92→      `,
 93→      text: `You're on the waitlist!\n\nThanks for signing up. We'll let you know as soon as delivery is available to ${zipCode}.\n\n— ${name}`,
 94→      ...buildReplyTo(options),
 95→    });
 96→    return true;
 97→  } catch (error) {
 98→    console.error("[email] Failed to send waitlist confirmation:", error);
 99→    return false;
100→  }
101→}
